/* Panes share the width through flex-grow factors, so the layout is right on the server and stays proportional as the group resizes. */
/* A size container, so each pane's floor can scale with the group when it is too narrow for every minimum (see --panel-min). */
.group { display: flex; width: 100%; height: 100%; min-width: 0; min-height: 0; overflow: hidden; container-type: inline-size; }
.group[data-resizing] { cursor: col-resize; user-select: none; -webkit-user-select: none; }
/* Content ignores the pointer while a divider moves, so hover states never flicker underneath it. */
.group[data-resizing] .content { pointer-events: none; }

/* CSS enforces each pane's limits until an interaction frees it; JS hands them back once the pane settles inside them. */
.panel { position: relative; display: flex; min-width: var(--panel-min); max-width: var(--panel-max); min-height: 0; flex: 0 1 0px; overflow: hidden; }
.panel[data-anchor="end"] { justify-content: flex-end; }
.panel[data-free], .panel[data-collapsed] { min-width: 0; max-width: none; }
.content { display: flex; width: 100%; flex: none; flex-direction: column; min-height: 0; }
.panel[data-free] .content, .panel[data-collapsed] .content { min-width: var(--panel-min); }

/* The divider is a one pixel line with a 13px grab area, and a grip that forms while it is hovered, focused, or dragged. */
.handle { position: relative; z-index: 2; flex: 0 0 1px; background: var(--border); cursor: col-resize; touch-action: none; outline: none; -webkit-tap-highlight-color: transparent; transition: background-color var(--duration-fast) var(--ease-standard); }
.handle::before { position: absolute; inset: 0 -6px; content: ""; }
.handle[data-collapsed] { background: transparent; cursor: pointer; }
.grip { position: absolute; top: 50%; left: 50%; width: 4px; height: 32px; border-radius: var(--radius-pill); background: var(--border-strong); opacity: 0; pointer-events: none; transform: translate(-50%, -50%) scaleY(.6); transition: opacity var(--duration-fast) var(--ease-standard), background-color var(--duration-fast) var(--ease-standard), transform var(--duration-spring) var(--ease-spring); }
@media (hover: hover) and (pointer: fine) {
  .handle:not([data-collapsed]):hover { background: var(--border-strong); }
  .handle:not([data-collapsed]):hover .grip { opacity: 1; transform: translate(-50%, -50%) scaleY(1); }
  .handle[data-collapsed]:hover .restore { border-color: var(--border-strong); color: var(--foreground); }
}
.handle[data-active] { background: var(--border-strong); }
.handle[data-active] .grip { background: var(--foreground); opacity: 1; transform: translate(-50%, -50%) scaleY(1); }
.handle:focus-visible:not([data-collapsed]) .grip { opacity: 1; outline: 2px solid var(--focus-ring); outline-offset: 2px; transform: translate(-50%, -50%) scaleY(1); }
.handle[data-collapsed]:focus-visible .restore { outline: 2px solid var(--focus-ring); outline-offset: 2px; }

/* Once a neighbour is hidden, a tab on the divider points the way it will come back. */
.restore { position: absolute; top: 50%; display: grid; width: 18px; height: 40px; margin-top: -20px; place-items: center; border: 1px solid var(--border); border-radius: var(--radius-pill); background: var(--surface); box-shadow: var(--shadow-resting); color: var(--text-secondary); pointer-events: none; transition: border-color var(--duration-fast) var(--ease-standard), color var(--duration-fast) var(--ease-standard); }
.restore[data-side="before"] { left: 5px; transform-origin: 0 50%; }
.restore[data-side="after"] { right: 5px; transform-origin: 100% 50%; }
.handle[data-collapsed]::before { inset: 0 -30px; }
.handle[data-collapsed="before"]::before { left: 0; }
.handle[data-collapsed="after"]::before { right: 0; }

@media (prefers-reduced-motion: reduce) {
  .handle, .grip, .restore { transition: none; }
}
